// The push guard of an agent: tells which gate file changes of a push range still need a human.
//
// A push or a pull request publishes the range from the push base to HEAD (gate-integrity.mjs,
// `range`). Some gate files are generated by Rush: an agent may push a range that changes only
// those, and only when the content passes a check (the `pushExempt` list of gate-files.json, read
// through `pushExemption`):
//   - common/config/rush/pnpm-lock.yaml (`agent-if-lock-clean`): a modified regular file whose new
//     text passes the lock lint against the old text (lock-lint.mjs): registry resolutions only, the
//     same header, the same integrity for every package that is in both locks.
//   - common/config/rush/repo-state.json (`agent-with-clean-lock`): a modified or added regular file
//     that holds only the Rush hash keys, and only together with a pnpm-lock.yaml change of the
//     same range that passes the lock lint. A hash change with no lock change is not exempt.
//   - rush.json (`agent-if-projects-added`): a modified regular file whose new text only adds
//     entries that register-project.mjs writes, with every old entry byte for byte the same
//     (rush-json-compare.mjs), and each added project has its projects/<name>/package.json at HEAD
//     with the name @vprprudhvi/<name>. A removal or an edit of an entry is not exempt.
// A delete, or a change to a symbolic link, is never exempt. The old text is the merge base, the new
// text is HEAD. Every other gate file in the range stays blocking. This module does not change
// `range`, `pushRange`, `uncommitted`, the Stop hook, the edit hook, the deny rules or check-gates
// (the CI risk label): those keep treating the exempt files as gate files. Any git failure throws
// or gives "blocking", never "exempt".
//
// The range starts at the merge base, so it cannot see a `git reset` that moved HEAD back past a
// human gate commit. `pushBlockers` also reads the saved session base (`savedSessionBase`) and
// reports the gate changes of the session base that HEAD lost (`rewoundChanges`): HEAD does not
// descend from the session base, and HEAD has other content than the session base in a gate file
// that the commits from the merge base to the session base change. A rebase keeps that content, so
// it is not reported. A branch that is behind origin/main is not reported: a merge, a squash or a
// rebase of the branch does not revert the gate changes of main. When the session base file is
// missing or does not name a commit, `pushBlockers` sets `missingBase`. Only the agent push guard
// (verify-gate.mjs, through the require-verify PreToolUse hook) calls `pushBlockers`. The git
// pre-push hook does not, so a human push from a terminal is not affected.
//
// The push base is the merge base of HEAD and origin/main (else origin/master, else the root
// commit). It does not use the upstream of the branch: `git branch -u` would move it.
import { describeChange, range, rewoundChanges, savedSessionBase } from './gate-integrity.mjs';
import { pushExemption } from './gate-list.mjs';
import { headSha } from './git-state.mjs';
import { lockProblems, repositoryStateIsPlain } from './lock-lint.mjs';
import { git, gitOrThrow } from './proc.mjs';
import { rushJsonAddedProjects } from './rush-json-compare.mjs';
import { PACKAGE_SCOPE } from './rush-json-edit.mjs';

/**
 * @typedef {import('./gate-integrity.mjs').GateChange} GateChange
 */

const GIT_FLAGS = ['--no-optional-locks'];
const LOCK_FILE = 'common/config/rush/pnpm-lock.yaml';
const BASE_REFS = ['origin/main', 'origin/master'];
const REGULAR_FILE_MODES = new Set(['100644', '100755']);
const EXEMPT_CHANGES = new Map([
  ['agent-if-lock-clean', new Set(['modified'])],
  ['agent-with-clean-lock', new Set(['modified', 'added'])],
  ['agent-if-projects-added', new Set(['modified'])],
]);

/**
 * Finds the commit where a push range starts: the merge base of HEAD and origin/main (else
 * origin/master), else the root commit. The upstream of the branch is not used.
 *
 * @param {string} root - Repo root.
 * @param {string} head - The last commit.
 * @returns {{ ref: string, sha: string } | null} The base, or null when the repo has no commit. It throws when git cannot find the root commit.
 */
function exemptionBase(root, head) {
  if (head === '') {
    return null;
  }
  for (const ref of BASE_REFS) {
    const found = git(root, [...GIT_FLAGS, 'rev-parse', '--verify', '--quiet', `${ref}^{commit}`]);
    const sha = found.stdout.trim();
    if (found.status === 0 && sha !== '') {
      const merge = git(root, [...GIT_FLAGS, 'merge-base', sha, head]);
      return {
        ref,
        sha: merge.status === 0 && merge.stdout.trim() !== '' ? merge.stdout.trim() : sha,
      };
    }
  }
  const roots = gitOrThrow(root, [...GIT_FLAGS, 'rev-list', '--max-parents=0', head])
    .stdout.trim()
    .split('\n')
    .filter((line) => line !== '');
  const oldest = roots.at(-1);
  if (oldest === undefined) {
    throw new Error('git rev-list found no root commit for HEAD');
  }
  return { ref: 'the root commit', sha: oldest };
}

/**
 * Reads the file mode of a path in a commit.
 *
 * @param {string} root - Repo root.
 * @param {string} commit - A commit.
 * @param {string} file - Path from the repo root.
 * @returns {string | null} The mode (`100644` for a regular file, `120000` for a link), or null when git does not have the path.
 */
function fileMode(root, commit, file) {
  const result = git(root, [...GIT_FLAGS, 'ls-tree', '-z', commit, '--', file]);
  if (result.status !== 0) {
    return null;
  }
  const record = result.stdout.split('\0')[0] ?? '';
  const tab = record.indexOf('\t');
  return tab !== -1 && record.slice(tab + 1) === file ? (record.split(' ')[0] ?? null) : null;
}

/**
 * Reads a file as it is stored in a commit.
 *
 * @param {string} root - Repo root.
 * @param {string} commit - A commit.
 * @param {string} file - Path from the repo root.
 * @returns {string | null} The text, or null when git cannot read it.
 */
function fileText(root, commit, file) {
  const result = git(root, [...GIT_FLAGS, 'cat-file', 'blob', `${commit}:${file}`]);
  return result.status === 0 ? result.stdout : null;
}

/**
 * Tells whether the pnpm lock change of the range is one that an agent may push.
 *
 * @param {string} root - Repo root.
 * @param {{ from: string, head: string }} ends - The merge base and the last commit of the range.
 * @param {GateChange[]} changes - The gate changes of the range.
 * @returns {boolean} True when the range modifies the lock (a regular file) and the new lock passes the lock lint against the old one. False on any doubt.
 */
function lockIsClean(root, ends, changes) {
  const change = changes.find((entry) => entry.file === LOCK_FILE);
  if (change?.change !== 'modified') {
    return false;
  }
  if (!REGULAR_FILE_MODES.has(fileMode(root, ends.head, LOCK_FILE) ?? '')) {
    return false;
  }
  const before = fileText(root, ends.from, LOCK_FILE);
  const after = fileText(root, ends.head, LOCK_FILE);
  return before !== null && after !== null && lockProblems(before, after).length === 0;
}

/**
 * Tells whether a project has its package.json at HEAD, with the name that rush.json gives it.
 *
 * @param {string} root - Repo root.
 * @param {string} head - The last commit.
 * @param {string} name - Project name.
 * @returns {boolean} True for a regular projects/<name>/package.json with the name @vprprudhvi/<name>.
 */
function hasProjectPackage(root, head, name) {
  const file = `projects/${name}/package.json`;
  if (!REGULAR_FILE_MODES.has(fileMode(root, head, file) ?? '')) {
    return false;
  }
  try {
    return JSON.parse(fileText(root, head, file) ?? '')?.name === `${PACKAGE_SCOPE}${name}`;
  } catch {
    return false;
  }
}

/**
 * Tells whether the rush.json change of the range only registers new projects.
 *
 * @param {string} root - Repo root.
 * @param {{ from: string, head: string }} ends - The merge base and the last commit of the range.
 * @param {string} file - Path of rush.json.
 * @returns {boolean} True when the change is pure additions of register-project.mjs entries and each added project has its package.json.
 */
function projectsAreRegistered(root, ends, file) {
  const before = fileText(root, ends.from, file);
  const after = fileText(root, ends.head, file);
  if (before === null || after === null) {
    return false;
  }
  const names = rushJsonAddedProjects(before, after);
  return names !== null && names.every((name) => hasProjectPackage(root, ends.head, name));
}

/**
 * Tells whether an agent may push a gate change.
 *
 * @param {{ root: string, ends: { from: string, head: string }, lockClean: () => boolean }} context - The repo root, the merge base and the last commit of the range, and a check that tells whether the lock change of the range passes the lock lint.
 * @param {GateChange} change - A change of the range.
 * @returns {boolean} True only for a change that the `pushExempt` list allows, with content that passes its check.
 */
function isPushable(context, change) {
  const { root, ends, lockClean } = context;
  const entry = pushExemption(change.file);
  if (entry === null || !(EXEMPT_CHANGES.get(entry.push)?.has(change.change) ?? false)) {
    return false;
  }
  if (!REGULAR_FILE_MODES.has(fileMode(root, ends.head, change.file) ?? '')) {
    return false;
  }
  if (entry.push === 'agent-if-lock-clean') {
    return lockClean();
  }
  if (entry.push === 'agent-with-clean-lock') {
    const text = fileText(root, ends.head, change.file);
    return lockClean() && text !== null && repositoryStateIsPlain(text);
  }
  return projectsAreRegistered(root, ends, change.file);
}

/**
 * Splits the gate changes of a range into the ones that an agent may push and the ones that need
 * a human.
 *
 * @param {string} root - Repo root.
 * @param {{ from: string, head: string }} ends - The merge base and the last commit of the range.
 * @param {GateChange[]} changes - The gate changes of the range (`range`).
 * @returns {{ blocking: GateChange[], exempt: GateChange[] }} The two lists, in the order of `changes`.
 */
export function splitPushChanges(root, ends, changes) {
  let verdict;
  const lockClean = () => {
    verdict ??= lockIsClean(root, ends, changes);
    return verdict;
  };
  const blocking = [];
  const exempt = [];
  for (const change of changes) {
    (isPushable({ root, ends, lockClean }, change) ? exempt : blocking).push(change);
  }
  return { blocking, exempt };
}

/**
 * Lists the gate changes that a push or a pull request would publish, split into the ones that
 * need a human and the ones that an agent may push. It also reports the gate changes of the session
 * base that HEAD lost (`rewound`, always blocking), and whether the saved session base is missing.
 *
 * @param {string} root - Repo root.
 * @returns {{ base: string, blocking: GateChange[], exempt: GateChange[], rewound: GateChange[], sessionBase: string | null, missingBase: boolean }} The base name, the two lists of the range, the lost gate changes, the saved session base, and true when the session base file is missing or does not name a commit (the caller fails closed). It throws when git fails.
 */
export function pushBlockers(root) {
  const head = headSha(root);
  const base = exemptionBase(root, head);
  if (base === null) {
    return {
      base: 'no commit',
      blocking: [],
      exempt: [],
      rewound: [],
      sessionBase: null,
      missingBase: false,
    };
  }
  const changes = range(root, base.sha, head);
  const session = savedSessionBase(root);
  return {
    base: base.ref,
    ...splitPushChanges(root, { from: base.sha, head }, changes),
    rewound: session === null ? [] : rewoundChanges(root, session),
    sessionBase: session,
    missingBase: session === null,
  };
}

/**
 * Writes the exempt files as one line of text.
 *
 * @param {GateChange[]} exempt - Exempt changes.
 * @returns {string} For example `common/config/rush/pnpm-lock.yaml (modified)`, comma separated.
 */
export function describeExempt(exempt) {
  return exempt.map((entry) => describeChange(entry)).join(', ');
}
